// Key capability index — record JAH-GPCS-SECURITYKEY-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"protocols": 3, "nfc": 1};
var value = (m.protocols*25+m.nfc*15);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-SECURITYKEY-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-SECURITYKEY-000001|' + value.toFixed(2) + ' capability index');

